-- TEC-24 Primo tocco orientato lontano dalla pressione (insert o aggiornamento)
-- Se il codice TEC-24 è già usato da un altro esercizio, prende il primo numero TEC libero.
with nuovo as (select '{"code":"TEC-24","title":"Primo tocco orientato lontano dalla pressione","area":"tecnica","fase":["attivazione","centrale"],"obiettivi":["ricezione","controllo orientato","postura del corpo","pressione","passaggio","lettura di gioco"],"eta":"U9-U13","giocatori":"4-5 per stazione (A con palloni, C ricevitore, D pressatore, B bersaglio)","spazio":"16x12 m, quadrato centrale 4x4 m","durata":10,"materiale":"4 cinesini per stazione, 1 casacca per il pressatore, palloni","perche":"Ricevere già sapendo da dove arriva la pressione: guardare prima, aprire il corpo e portare la palla con il primo tocco lontano dall’avversario, poi giocare subito in avanti. Situazione di gara continua per tutti i ruoli.","descrizione":"Setup: quadrato di 4 cinesini (4x4 m) al centro. A con i palloni a 6 m da un lato del quadrato, B bersaglio a 6 m dal lato opposto. C nel quadrato. D (casacca) fuori dal quadrato, vicino a B, spostato su un lato.\nEsecuzione: A passa a C. Alla partenza della palla D entra a pressare C da un lato (a scelta di D). C guarda prima di ricevere, capisce da dove arriva D e con il primo tocco porta la palla dal lato opposto, fuori dal quadrato. Poi passa a B.\nD pressa forte ma frena: non entra in contrasto (pressione passiva o al 50%).","rotazione":"A → ricevitore C. C → pressatore D. D → bersaglio B. B torna in fila A con la palla in conduzione.","varianti":"D sceglie il lato all’ultimo momento. D pressa al 100% e prova a rubare palla. Uscita solo dai lati del quadrato (non di fronte). Passaggio a B entro 2 tocchi. Con 2 bersagli (B a destra e a sinistra): C gioca sul bersaglio lontano da D.","coaching":"Prima del passaggio: girare la testa e guardare dove si trova D. Corpo aperto (di tre quarti), ricevere col piede lontano da D. Primo tocco deciso, fuori dalla zona di pressione, non sotto il corpo. Testa alta dopo il controllo e passaggio subito su B. Pressatore: corsa veloce, poi passi corti e frenata.","fonte":"Video drill crossfootballacademy – \"Directional first touch away from pressure\" (inviato da Andrea, 29/10/2026)","diagram":{"field":{"preset":"spazio","w":16,"h":12},"steps":[{"title":"A passa a C","note":"D parte e pressa C da un lato"},{"title":"Primo tocco orientato","note":"C porta la palla dal lato opposto a D, fuori dal quadrato"},{"title":"Passaggio a B","note":"C gioca subito su B"},{"title":"Rotazione","note":"A → C, C → D, D → B, B in fila A"}],"items":[{"id":"it1201","type":"disc","pos":{"0":{"x":6,"y":4}}},{"id":"it1202","type":"disc","pos":{"0":{"x":10,"y":4}}},{"id":"it1203","type":"disc","pos":{"0":{"x":6,"y":8}}},{"id":"it1204","type":"disc","pos":{"0":{"x":10,"y":8}}},{"id":"it1205","type":"playerA","pos":{"0":{"x":1.5,"y":6}},"label":"A"},{"id":"it1206","type":"playerA","pos":{"0":{"x":0.6,"y":7.4}},"label":"A"},{"id":"it1207","type":"playerA","pos":{"0":{"x":8,"y":6},"1":{"x":8,"y":6},"2":{"x":11.2,"y":9}},"label":"C"},{"id":"it1208","type":"playerB","pos":{"0":{"x":12.5,"y":2.2},"1":{"x":9.2,"y":4.9},"2":{"x":10.2,"y":6.8}},"label":"D"},{"id":"it1209","type":"playerA","pos":{"0":{"x":14.8,"y":6}},"label":"B"},{"id":"it1210","type":"ball","pos":{"0":{"x":2.1,"y":6.3},"1":{"x":7.4,"y":6.3},"2":{"x":11.8,"y":9.3},"3":{"x":14.2,"y":6.3}}}],"arrows":[{"id":"ar1211","kind":"pass","step":0,"from":{"x":2.1,"y":6.3},"to":{"x":7.4,"y":6.3}},{"id":"ar1212","kind":"run","step":0,"from":{"x":12.5,"y":2.2},"to":{"x":9.2,"y":4.9},"curve":-1},{"id":"ar1213","kind":"dribble","step":1,"from":{"x":8,"y":6},"to":{"x":11.2,"y":9},"curve":1},{"id":"ar1214","kind":"run","step":1,"from":{"x":9.2,"y":4.9},"to":{"x":10.2,"y":6.8}},{"id":"ar1215","kind":"pass","step":2,"from":{"x":11.8,"y":9.3},"to":{"x":14.2,"y":6.3}}]},"id":"5eed0000-0000-4000-8000-000000000141","updatedAt":"2026-10-29T00:00:00.000Z"}'::jsonb as d),
codice as (
  select coalesce(
    (select data->>'code' from public.exercises where id = '5eed0000-0000-4000-8000-000000000141'),
    case when exists (select 1 from public.exercises where data->>'code' = 'TEC-24' and id <> '5eed0000-0000-4000-8000-000000000141')
      then 'TEC-' || lpad((select max(substring(data->>'code' from 5)::int) + 1 from public.exercises where data->>'code' ~ '^TEC-[0-9]+$')::text, 2, '0')
      else 'TEC-24' end
  ) as c
)
insert into public.exercises (id, data, updated_at)
select '5eed0000-0000-4000-8000-000000000141', jsonb_set(nuovo.d, '{code}', to_jsonb(codice.c)), now() from nuovo, codice
on conflict (id) do update set data = excluded.data, updated_at = now();
select id, data->>'code' code, data->>'title' title from public.exercises where data->>'code' like 'TEC-%' order by 2;
